    // Trash (CPE-1560, epic CPE-1486): the sidebar entry + browsable Trash view + Restore/Empty actions.
    "sidebar.trash": "Trash",
    "trash.open": "Open Trash",
    "trash.openTip": "Browse deleted files and folders",
    "trash.macLabel": "Open Finder's Trash instead",
    "trash.macMessage": "Browsing the Trash isn't available on macOS yet. Open Finder's Trash to restore or empty deleted items.",
    "trash.title": "Trash",
    "trash.loading": "Loading Trash…",
    "trash.empty": "Trash is empty",
    // CPE-1803: a *third* state, distinct from both "trash.empty" and "trash.error" — the listing
    // finished without throwing (so it's not "trash.error"'s genuine failure), but it degraded to no
    // entries because the OS trash couldn't be fully read (so it's not really "trash.empty" either).
    // Wording deliberately avoids "broken"/"corrupted": the entries are still there and restore still
    // works for anything visible — only THIS listing pass came back thin, and it self-heals once the
    // underlying condition clears. Nothing here is fixable from inside the app, so it says what
    // happened, not what to do about it.
    "trash.degraded": "Trash couldn't be fully read — it may not be empty",
    // CPE-1804: the OTHER way a listing comes back incomplete — individual items dropped because
    // their id/name/original path isn't valid UTF-8. Split from "trash.degraded" because this route
    // knows HOW MANY it dropped and the caught-panic route doesn't, and a number is the difference
    // between knowing how much is missing and only knowing that something is. Says "couldn't be read"
    // rather than naming UTF-8: the cause is not actionable from in here, the consequence is.
    "trash.skippedOne": "1 item in the Trash couldn't be read and isn't shown",
    "trash.skippedMany": "{count} items in the Trash couldn't be read and aren't shown",
    // CPE-1816: the stream's summary (and with it `degraded`/`skipped`) arrives only once the walk
    // ends, so while batches are still landing the app genuinely doesn't know yet whether this pass
    // will turn out degraded. Shown instead of an item count during that window, never alongside one —
    // asserting "N items" here would be the same premature claim this ticket exists to stop making.
    "trash.stillLoading": "Still loading…",
    "trash.error": "Couldn't load the Trash: {error}",
